# Operator 82 sites: KS-1868 coercing-String follow-up on files already merged (G113-F1/F2 auth, G114-F1/F2 anchors).
SV='Blockchain/Dev/services/'
AU=SV+'auth/'; AN=SV+'anchoring/'; OR=SV+'originate/'
NEWA=lambda s,expr: s+"const m = "+expr+";\n"+s+"reason = m === undefined || m === null ? m : String(m);\n"
def _ed(ind, tail, expr, form):
    s=' '*ind; l=' '*(ind-2)
    old=l+"let reason: string;\n"+l+"try {\n"+s+"reason = "+expr+";\n"+l+"} catch {\n"+s+"reason = 'unreadable thrown value';\n"+l+"}\n"+tail
    if form=='A': new=old.replace(s+"reason = "+expr+";\n", NEWA(s,expr),1)
    else:
        assert expr=='err instanceof Error ? err.message : String(err)' or expr=='error instanceof Error ? error.message : String(error)'
        v='error' if expr.startswith('error') else 'err'
        new=old.replace("reason = "+expr+";","reason = String(%s instanceof Error ? %s.message : %s);"%(v,v,v),1)
    return (old,new)
FORM_A="`const m = <the same read>; reason = m === undefined || m === null ? m : String(m);` inside the same `try`"
SAFE_FORM_A_WHY=("Here the read is first taken into a local `m` and `String(...)` is applied only when `m` is neither undefined nor null, because a thrown plain string (or any value with no message) has no message and today is logged with no `error` value; a bare `String(...)` would newly log the text 'undefined' for those. No helper.")
SAFE_FORM_B_WHY=("This site already turns a non-Error throw into text (`String(err)`), so the coercion is `String(err instanceof Error ? err.message : err)` inside the same `try`: a non-Error is still stringified exactly as before and only an Error's message is newly coerced. No helper.")
HOST_PROSE="If the getter succeeds and returns a hostile NON-string (a revoked Proxy, an object whose `toString` throws, a null-prototype object, a Symbol), the value is passed on uncoerced and the real logger can throw while formatting it, INSIDE the catch, outside the guard"
COMMON=dict(key='KS-1868', runner='vitest', runcmd='run ')
def reuse(why): return ("This follows the coercing form that PR 1924 merged for the `originate` outer catches and that operator 80 and 81's held passes use (`String(...)` of the read inside the same `try`/`catch { reason = 'unreadable thrown value' }`), applied to the guards that PR %s already merged in this very file. "+why)
T={}
